<?php
require_once __DIR__ . '/_bootstrap.php'; b2cRequireCustomer();
$uid=(int)currentUserId();$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken();$pid=(int)($_POST['product_id']??0);$qty=max(0,min(99,(int)($_POST['quantity']??0)));$cartId=(int)(b2cQuery('SELECT id FROM carts WHERE user_id=? AND status="active" LIMIT 1',[$uid])?->fetchColumn()??0);if($cartId)$s=$qty===0?b2cQuery('DELETE FROM cart_items WHERE cart_id=? AND product_id=?',[$cartId,$pid]):b2cQuery('UPDATE cart_items SET quantity=? WHERE cart_id=? AND product_id=?',[$qty,$cartId,$pid]);else $s=null;$notice=$s?'Cart updated.':'We could not update your cart.';}
$items=b2cRows("SELECT ci.product_id,ci.quantity,p.name,p.sku,p.retail_price,(ci.quantity*p.retail_price) subtotal,(SELECT pi.image FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.is_primary DESC,pi.sort_order LIMIT 1) image FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id AND p.status='active' WHERE c.user_id=? AND c.status='active' ORDER BY ci.id DESC",[$uid]);$total=array_sum(array_map(static fn($i)=>(float)$i['subtotal'],$items));
b2cPage('Your cart'); ?>
<div class="section-head"><div><h1>Your cart</h1><p><?= count($items) ?> item<?=count($items)===1?'':'s'?> ready when you are.</p></div></div><?php if($notice): ?><div class="alert"><?= e($notice) ?></div><?php endif; ?>
<?php if(!$items): ?><div class="empty"><h2>Your cart is waiting</h2><p>Add something you love and it will show up here.</p><a class="btn gold" href="products.php">Continue shopping</a></div><?php else: ?><div class="layout"><section class="panel"><table class="table"><thead><tr><th>Product</th><th>Quantity</th><th>Price</th><th></th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><strong><?= e($i['name']) ?></strong><br><span class="muted"><?= e($i['sku']??'') ?></span></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="product_id" value="<?= (int)$i['product_id'] ?>"><input class="qty" data-autosubmit type="number" name="quantity" min="0" max="99" value="<?= (int)$i['quantity'] ?>"></form></td><td class="price"><?= e(formatPrice($i['subtotal'])) ?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="product_id" value="<?= (int)$i['product_id'] ?>"><input type="hidden" name="quantity" value="0"><button class="btn light" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></section><aside class="panel"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><strong><?= e(formatPrice($total)) ?></strong></div><div class="summary-line"><span>Delivery</span><span class="muted">Calculated at checkout</span></div><div class="summary-line total"><strong>Total</strong><strong><?= e(formatPrice($total)) ?></strong></div><a class="btn gold" href="checkout.php">Proceed to checkout</a></aside></div><?php endif; ?><?php b2cEnd(); ?>